function isUpDownUp(nums: number[]): boolean {
  const n = nums.length;
  const rising = (lo: number, hi: number) => {
    for (let i = lo; i < hi; i++) if (nums[i] >= nums[i + 1]) return false;
    return true;
  };
  const falling = (lo: number, hi: number) => {
    for (let i = lo; i < hi; i++) if (nums[i] <= nums[i + 1]) return false;
    return true;
  };
  for (let p = 1; p < n - 2; p++) {
    for (let q = p + 1; q < n - 1; q++) {
      if (rising(0, p) && falling(p, q) && rising(q, n - 1)) return true;
    }
  }
  return false;
}

