class Solution:
    def isUpDownUp(self, nums: List[int]) -> bool:
        n = len(nums)
        def rising(lo, hi):
            return all(nums[i] < nums[i + 1] for i in range(lo, hi))
        def falling(lo, hi):
            return all(nums[i] > nums[i + 1] for i in range(lo, hi))
        for p in range(1, n - 2):
            for q in range(p + 1, n - 1):
                if rising(0, p) and falling(p, q) and rising(q, n - 1):
                    return True
        return False

