function isUpDownUp(nums: number[]): boolean {
  const n = nums.length;
  let i = 0;
  while (i + 1 < n && nums[i] < nums[i + 1]) i++;
  if (i === 0) return false;
  const p = i;
  while (i + 1 < n && nums[i] > nums[i + 1]) i++;
  if (i === p || i === n - 1) return false;
  const q = i;
  while (i + 1 < n && nums[i] < nums[i + 1]) i++;
  return i !== q && i === n - 1;
}

